package org.formasaloido;

import java.util.*;

/** The math workspace uses the same contact, scan and playback grammar as images and figures. */
public final class MathExploration {
 public static Geometry geometry(int kind,int filter){if(filter<0||filter>2)throw new IllegalArgumentException("Filtro matemático no válido.");Geometry source=MathLesson.plane(kind);List<Geometry.Shape> selected=new ArrayList<>();for(int i=0;i<source.shapes.size();i++)if(filter==0||filter==1&&i>=2||filter==2&&i<2)selected.add(source.shapes.get(i));return new Geometry(source.seed,selected);}
 public static boolean graduated(Geometry.Point p){return p.x>=100&&p.x<=500&&p.y>=25&&p.y<=425;}
 public static String at(int kind,Geometry.Point p){MathLesson.plane(kind);if(!Double.isFinite(p.x)||!Double.isFinite(p.y))throw new IllegalArgumentException("Posición no válida.");if(p.x<0||p.x>600||p.y<0||p.y>450)return "Fuera del lienzo.";if(p.x<12||p.x>588||p.y<12||p.y>438)return "Marco del lienzo. "+(p.x<12?"Borde izquierdo. ":p.x>588?"Borde derecho. ":"")+(p.y<12?"Borde superior.":p.y>438?"Borde inferior.":"");if(!graduated(p))return "Zona de referencia entre el plano graduado y el marco del lienzo. El espacio vacío puede sonar como aire tenue.";return MathLesson.at(kind,(p.x-300)/40,(225-p.y)/40);}
 public static Sound.Program frame(Sound.Settings settings){return new Sound.Program(settings).path(Curriculum.points(0,0,600,0,600,450,0,450,0,0),false,true);}
 public static Sound.Program reference(Sound.Settings settings){Sound.Program p=new Sound.Program(settings).pulse(new Geometry.Point(300,225),0,.4,"vertex").silence(.3);for(Geometry.Point corner:Curriculum.points(0,0,600,0,600,450,0,450))p.pulse(corner,0,.25,"vertex").silence(.2);return p;}
 public static String element(Geometry.Element e,int level){Geometry.Point a=e.points.get(0),b=e.points.get(e.points.size()-1);String prefix=Geometry.description(e,level);String start=MathLesson.coordinate((a.x-300)/40,(225-a.y)/40);return prefix+" Inicio: "+start+(e.points.size()>1?" Final: "+MathLesson.coordinate((b.x-300)/40,(225-b.y)/40):"");}
 public static final class Scan {public final Sound.Program program;public final String description;public final int count;Scan(Sound.Program p,String d,int n){program=p;description=d;count=n;}}
 public static Scan scan(int kind,int filter,Sound.Settings settings,int mode,Geometry.Point origin,int step,int section,boolean invert){if(mode<0||mode>4||step<16||step>80||section< -1||!Double.isFinite(origin.x)||!Double.isFinite(origin.y)||origin.x<0||origin.x>600||origin.y<0||origin.y>450)throw new IllegalArgumentException("Parámetros de barrido no válidos.");Geometry g=geometry(kind,filter);if(mode==3){boolean closed=false;for(Geometry.Shape shape:g.shapes)closed|=shape.closed;if(!closed)throw new IllegalArgumentException("No hay regiones cerradas con este filtro. Usa filas, columnas, cuadrantes o contorno.");}if(mode==4){if(section>0)throw new IllegalArgumentException("El contorno tiene una sola sección.");return new Scan(ImageScan.contour(g,settings,origin),"Contorno desde la referencia elegida.",1);}ImageScan scan=new ImageScan(g,null,settings,mode,origin,step,128,255,invert);if(section>=scan.sections.size())throw new IllegalArgumentException("Final del barrido. Vuelve a la primera sección.");return new Scan(scan.program(settings,section),(section<0?"Barrido completo: "+scan.sections.size()+" secciones.":scan.sections.get(section).name+" de un total de "+scan.sections.size()+".")+" Los tonos más tenues representan espacio vacío; no son contornos inventados.",scan.sections.size());}
}
